  `resultados` text DEFAULT NULL COMMENT 'Resultados de la revisión por Normatividad',
  `estado_normatividad` enum('en_revision','aceptada','rechazada') DEFAULT NULL COMMENT 'Estado de respuesta por Normatividad',
  `usuario_creador_id` int(11) NOT NULL COMMENT 'ID del usuario de Ventas que creó',
  `departamento_creador` varchar(100) NOT NULL DEFAULT 'ventas',
  `departamento_id` int(11) DEFAULT NULL,
  `usuario_normatividad_id` int(11) DEFAULT NULL COMMENT 'ID del usuario de Normatividad que atendió',
  `estado` enum('enviada','en_revision','aceptada','rechazada') NOT NULL DEFAULT 'enviada' COMMENT 'Estado interno del sistema',
  `ubicacion` enum('local','global') NOT NULL DEFAULT 'local' COMMENT 'local = en proceso, global = completado',
  `fecha_creacion` datetime NOT NULL DEFAULT current_timestamp(),
  `fecha_ultima_edicion` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `fecha_enviada` datetime DEFAULT NULL COMMENT 'Cuando Ventas envió a Normatividad',
  `fecha_en_revision` datetime DEFAULT NULL COMMENT 'Cuando Normatividad comenzó revisión',
  `fecha_aceptada` datetime DEFAULT NULL COMMENT 'Cuando Normatividad aceptó la cotización',
  `fecha_rechazada` datetime DEFAULT NULL COMMENT 'Cuando Normatividad rechazó la cotización',
  `fecha_respuesta_normatividad` datetime DEFAULT NULL COMMENT 'Cuando Normatividad envió su respuesta'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Solicitudes de Cotización de Químicos y/o Residuos';

