  `departamento` varchar(100) NOT NULL,
  `departamento_id` int(11) DEFAULT NULL,
  `empresa` enum('RESIMEX','CARGANOVA') NOT NULL,
  `estado` enum('pendiente_mantenimiento','en_proceso','pendiente_usuario','devuelto','completado') DEFAULT 'pendiente_mantenimiento',
  `apartado1_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Datos llenados por el usuario solicitante' CHECK (json_valid(`apartado1_data`)),
  `apartado2_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Datos llenados por el área de mantenimiento' CHECK (json_valid(`apartado2_data`)),
  `apartado3_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Firmas y cierre de orden' CHECK (json_valid(`apartado3_data`)),
  `fecha_creacion` datetime DEFAULT current_timestamp() COMMENT 'Fecha creación de la orden',
  `fecha_primera_edicion_mant` datetime DEFAULT NULL COMMENT 'Primera vez que Mantenimiento presionó EDITAR',
  `fecha_primer_guardado_mant` datetime DEFAULT NULL COMMENT 'Primera vez que Mantenimiento presionó GUARDAR',
  `fecha_enviado_usuario` datetime DEFAULT NULL COMMENT 'Fecha cuando Mantenimiento envió a Usuario',
  `fecha_completado` datetime DEFAULT NULL COMMENT 'Fecha cuando Usuario finalizó la orden',
  `fecha_ultima_modificacion` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `usuario_ultima_modificacion_id` int(11) DEFAULT NULL,
  `usuario_ultima_modificacion_nombre` varchar(255) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Órdenes de Servicio para Mantenimiento - Sistema con apartados JSON';

--
-- Volcado de datos para la tabla `ordenes_servicio_mantenimiento`
--


--
-- Disparadores `ordenes_servicio_mantenimiento`
--
DELIMITER $$
CREATE TRIGGER `trg_primera_edicion_mant` BEFORE UPDATE ON `ordenes_servicio_mantenimiento` FOR EACH ROW BEGIN
    -- Si apartado2_data se actualiza por primera vez y fecha_primera_edicion_mant es NULL
    IF NEW.apartado2_data IS NOT NULL 
       AND OLD.apartado2_data IS NULL 
       AND OLD.fecha_primera_edicion_mant IS NULL THEN
        SET NEW.fecha_primera_edicion_mant = CURRENT_TIMESTAMP;
    END IF;
END
$$
DELIMITER ;

