  `user_id` int(11) NOT NULL COMMENT 'ID del usuario',
  `lector` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Permiso de lectura',
  `creador` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Permiso de crear cotizaciones (Ventas)',
  `editor` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Permiso de editar/responder (Normatividad)',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT NULL ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Permisos de usuarios para módulo Cotizaciones Químicos/Residuos (CQR)';

--
-- Volcado de datos para la tabla `permisos_cqr`
--


--
-- Disparadores `permisos_cqr`
--
DELIMITER $$
CREATE TRIGGER `trg_permisos_cqr_before_insert` BEFORE INSERT ON `permisos_cqr` FOR EACH ROW BEGIN
    -- Si es editor o creador, lector debe ser 1
    IF NEW.editor = 1 OR NEW.creador = 1 THEN
        SET NEW.lector = 1;
    END IF;
END
$$
DELIMITER ;
