CREATE TRIGGER `trg_permisos_cqr_before_update` BEFORE UPDATE ON `permisos_cqr` FOR EACH ROW BEGIN
    -- Si es editor o creador, lector debe ser 1
    IF NEW.editor = 1 OR NEW.creador = 1 THEN
        SET NEW.lector = 1;
    END IF;
END
$$
DELIMITER ;

