--
-- Estructura para la vista `v_estadisticas_departamento`
--
DROP TABLE IF EXISTS `v_estadisticas_departamento`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_estadisticas_departamento`  AS SELECT `ordenes_servicio_mantenimiento`.`departamento` AS `departamento`, count(0) AS `total_ordenes`, sum(case when `ordenes_servicio_mantenimiento`.`estado` = 'pendiente_mantenimiento' then 1 else 0 end) AS `pendientes`, sum(case when `ordenes_servicio_mantenimiento`.`estado` = 'en_proceso' then 1 else 0 end) AS `en_proceso`, sum(case when `ordenes_servicio_mantenimiento`.`estado` = 'pendiente_usuario' then 1 else 0 end) AS `pendientes_validacion`, sum(case when `ordenes_servicio_mantenimiento`.`estado` = 'devuelto' then 1 else 0 end) AS `devueltas`, sum(case when `ordenes_servicio_mantenimiento`.`estado` = 'completado' then 1 else 0 end) AS `completadas`, avg(to_days(coalesce(`ordenes_servicio_mantenimiento`.`fecha_completado`,curdate())) - to_days(cast(`ordenes_servicio_mantenimiento`.`fecha_creacion` as date))) AS `promedio_dias` FROM `ordenes_servicio_mantenimiento` GROUP BY `ordenes_servicio_mantenimiento`.`departamento` ;

-- --------------------------------------------------------

--
-- Estructura para la vista `v_ordenes_activas`
--
DROP TABLE IF EXISTS `v_ordenes_activas`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_ordenes_activas`  AS SELECT `ordenes_servicio_mantenimiento`.`id` AS `id`, `ordenes_servicio_mantenimiento`.`folio` AS `folio`, `ordenes_servicio_mantenimiento`.`estado` AS `estado`, `ordenes_servicio_mantenimiento`.`usuario_nombre` AS `usuario_nombre`, `ordenes_servicio_mantenimiento`.`departamento` AS `departamento`, `ordenes_servicio_mantenimiento`.`empresa` AS `empresa`, `ordenes_servicio_mantenimiento`.`fecha_creacion` AS `fecha_creacion`, to_days(curdate()) - to_days(cast(`ordenes_servicio_mantenimiento`.`fecha_creacion` as date)) AS `dias_desde_creacion`, json_unquote(json_extract(`ordenes_servicio_mantenimiento`.`apartado1_data`,'$.prioridad')) AS `prioridad`, json_unquote(json_extract(`ordenes_servicio_mantenimiento`.`apartado1_data`,'$.unidad_equipo')) AS `unidad_equipo` FROM `ordenes_servicio_mantenimiento` WHERE `ordenes_servicio_mantenimiento`.`estado` in ('pendiente_mantenimiento','en_proceso','devuelto') ORDER BY `ordenes_servicio_mantenimiento`.`fecha_creacion` DESC ;

-- --------------------------------------------------------

--
-- Estructura para la vista `v_ordenes_completadas`
--
DROP TABLE IF EXISTS `v_ordenes_completadas`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_ordenes_completadas`  AS SELECT `ordenes_servicio_mantenimiento`.`id` AS `id`, `ordenes_servicio_mantenimiento`.`folio` AS `folio`, `ordenes_servicio_mantenimiento`.`usuario_nombre` AS `usuario_nombre`, `ordenes_servicio_mantenimiento`.`departamento` AS `departamento`, `ordenes_servicio_mantenimiento`.`empresa` AS `empresa`, `ordenes_servicio_mantenimiento`.`fecha_creacion` AS `fecha_creacion`, `ordenes_servicio_mantenimiento`.`fecha_completado` AS `fecha_completado`, to_days(cast(`ordenes_servicio_mantenimiento`.`fecha_completado` as date)) - to_days(cast(`ordenes_servicio_mantenimiento`.`fecha_creacion` as date)) AS `dias_total` FROM `ordenes_servicio_mantenimiento` WHERE `ordenes_servicio_mantenimiento`.`estado` = 'completado' ORDER BY `ordenes_servicio_mantenimiento`.`fecha_completado` DESC ;

